// pubspec.yaml: workmanager: ^0.5.2
import 'package:workmanager/workmanager.dart';

// ────── TOP-LEVEL callback — required — @pragma('vm:entry-point') for release ──────
@pragma('vm:entry-point')
void callbackDispatcher() {
  Workmanager().executeTask((task, inputData) async {
    // NEW isolate — must re-init dependencies:
    WidgetsFlutterBinding.ensureInitialized();
    await Firebase.initializeApp();
    Hive.registerAdapter(...);
    await Hive.openBox('outbox');

    switch (task) {
      case 'syncOutbox':
        final box = Hive.box('outbox');
        for (final k in box.keys) {
          try { await api.post(box.get(k)); await box.delete(k); }
          catch (_) { return false; }   // false → retry with backoff
        }
        return true;
      case 'fetchFeed':
        await feedRepo.refresh();
        return true;
    }
    return true;
  });
}

// ────── Main isolate init ──────
Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp();
  await Workmanager().initialize(callbackDispatcher, isInDebugMode: kDebugMode);
  runApp(const MyApp());
}

// ────── One-off with constraints ──────
await Workmanager().registerOneOffTask(
  'sync-outbox-once', 'syncOutbox',
  constraints: Constraints(networkType: NetworkType.connected, batteryNotLow: true),
  backoffPolicy: BackoffPolicy.exponential,
  backoffPolicyDelay: const Duration(minutes: 1),
  inputData: {'reason': 'user_tap'},
);

// ────── Periodic hourly (Android reliable, iOS best-effort) ──────
await Workmanager().registerPeriodicTask(
  'feed-fetch', 'fetchFeed',
  frequency: const Duration(hours: 1),
  constraints: Constraints(networkType: NetworkType.unmetered),
);

// ────── Cancel ──────
await Workmanager().cancelByUniqueName('feed-fetch');
await Workmanager().cancelAll();
